// Offline import audit: game assets are only read. No game, GUI or network is started.
using Aurora.Core;using Aurora.Editor;using System.Text.Json;using System.Text.RegularExpressions;
if(args.Length!=2)throw new ArgumentException("Usage: MaterialAudit <media_soviet> <output.json>");
string media=Path.GetFullPath(args[0]),output=Path.GetFullPath(args[1]);
var objects=VehicleCatalog.Load(media,true).Objects;var failures=new List<object>();var unsupported=new List<object>();var partial=new List<object>();var counts=new Dictionary<string,int[]>();int variants=0;
foreach(var obj in objects){if(!counts.TryGetValue(obj.Type,out var count))counts[obj.Type]=count=new int[4];count[0]++;string folder=Path.GetDirectoryName(obj.Script)!,main=Path.Combine(folder,"main.nmf");if(!File.Exists(main)){unsupported.Add(new{obj.Id,Reason="No main.nmf"});continue;}NativeModel model;try{model=new(File.ReadAllBytes(main));count[1]++;}catch(Exception ex){unsupported.Add(new{obj.Id,Reason=ex.Message});continue;}
var files=Directory.GetFiles(folder,"*.mtl").Where(f=>Regex.IsMatch(Path.GetFileName(f),@"^material(?:_\d+)?\.mtl$",RegexOptions.IgnoreCase)).OrderBy(f=>Path.GetFileName(f).Length).ThenBy(f=>f).ToArray();if(files.Length==0){count[3]++;continue;}try{var canonical=ModelEditing.NativeMaterialSlots(model,NativeMaterialText.Names(File.ReadAllText(files[0])),allowPartial:true);foreach(string file in files){var maps=MaterialDocuments.Native(file,canonical);if(MaterialFiles.Companion(file) is string pbr)maps=MaterialDocuments.Pbr(pbr,maps);var missing=canonical.Nodes.SelectMany(n=>n.Groups).Select(g=>canonical.Materials[g.Material]).Distinct().Where(n=>!maps.ContainsKey(n)).ToArray();if(missing.Length>0)partial.Add(new{obj.Id,Variant=Path.GetFileName(file),Missing=missing});variants++;}count[2]++;}catch(Exception ex){failures.Add(new{obj.Id,obj.Type,Reason=ex.Message});}}
var report=new{Objects=objects.Length,Variants=variants,Columns=new[]{"Objects","RigidMain","MaterialImportPass","NoMTL"},Counts=counts,Failures=failures,Partial=partial,Unsupported=unsupported};Directory.CreateDirectory(Path.GetDirectoryName(output)!);File.WriteAllText(output,JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(new{report.Objects,report.Variants,report.Counts,Failures=failures.Count,PartialObjects=partial.Select(p=>JsonSerializer.SerializeToElement(p).GetProperty("Id").GetString()).Distinct().Count(),PartialVariants=partial.Count,Unsupported=unsupported.Count}));foreach(var failure in failures.Take(8))Console.WriteLine(JsonSerializer.Serialize(failure));
